package dev.goforge.containers;
import com.google.gson.JsonParser;
import org.junit.Test;
import java.nio.file.*;
import java.util.*;
import static org.junit.Assert.*;
public class DevContainerPlanTest {
    @Test public void jsonCommentsAndTrailingCommasDoNotChangeQuotedContent(){var json=JsonParser.parseString(DevContainerPlan.jsonc("{/*comment*/\"url\":\"https://a/*not-comment*/,\",//line\n\"items\":[1,],}"));assertEquals("https://a/*not-comment*/,",json.getAsJsonObject().get("url").getAsString());assertEquals(1,json.getAsJsonObject().getAsJsonArray("items").size());}
    @Test public void basicProjectionNeverImportsHostHooksMountsOrLifecycle()throws Exception{with("{\"image\":\"example:tag\",\"initializeCommand\":\"touch /host\",\"postCreateCommand\":\"echo deferred\",\"runArgs\":[\"--privileged\"],\"mounts\":[\"source=/,target=/host,type=bind\"]}",p->{var generated=JsonParser.parseString(p.configuration()).getAsJsonObject();assertFalse(generated.has("initializeCommand"));assertFalse(generated.has("postCreateCommand"));assertFalse(generated.has("mounts"));assertFalse(p.configuration().contains("--privileged"));assertTrue(p.omitted().containsAll(List.of("initializeCommand","runArgs","mounts")));assertEquals(List.of(List.of("/bin/sh","-c","echo deferred")),DevContainerPlan.commands(p.lifecycle()));assertTrue(p.up("node",Path.of("cli.js"),"docker",Path.of("generated.json")).contains("--skip-post-create"));});}
    @Test public void configurationChangesRequireNewReview()throws Exception{with("{\"image\":\"example:tag\"}",p->{p.requireUnchanged();Files.writeString(p.source(),"{\"image\":\"other:tag\"}");assertThrows(IllegalStateException.class,p::requireUnchanged);});}
    @Test public void suffixAndUnsupportedComposeAreRejected()throws Exception{Path root=Files.createTempDirectory("goforge-dev-");Path file=Files.writeString(root.resolve("devcontainer.json"),"{\"dockerComposeFile\":\"compose.yaml\"}");try{assertThrows(IllegalArgumentException.class,()->DevContainerPlan.read(root,file,"name"));assertThrows(IllegalArgumentException.class,()->DevContainerPlan.read(root,file,"--privileged"));}finally{Files.delete(file);Files.delete(root);}}
    @Test public void deferredCommandsAreTypedAndObjectsHaveDefinedSequentialOrder(){assertEquals(List.of(List.of("echo","literal ; &")),DevContainerPlan.commands("[\"echo\",\"literal ; &\"]"));assertEquals(2,DevContainerPlan.commands("{\"first\":\"echo first\",\"second\":[\"echo\",\"second\"]}").size());assertThrows(IllegalArgumentException.class,()->DevContainerPlan.commands("42"));}
    @Test public void buildPathsAreResolvedRelativeToConfigAndStayInsideWorkspace()throws Exception{Path root=Files.createTempDirectory("goforge-dev-build-");Path dir=Files.createDirectory(root.resolve(".devcontainer"));Path df=Files.writeString(dir.resolve("Dockerfile"),"FROM scratch\n");Path cfg=Files.writeString(dir.resolve("devcontainer.json"),"{\"build\":{\"context\":\"..\",\"dockerfile\":\"Dockerfile\",\"args\":{\"FOO\":\"bar\"}}}");try{var p=DevContainerPlan.read(root,cfg,"test");var build=JsonParser.parseString(p.configuration()).getAsJsonObject().getAsJsonObject("build");assertEquals(root.toRealPath().toString(),build.get("context").getAsString());assertEquals(df.toRealPath().toString(),build.get("dockerfile").getAsString());}finally{Files.delete(cfg);Files.delete(df);Files.delete(dir);Files.delete(root);}}
    private interface Check{void run(DevContainerPlan plan)throws Exception;}
    private void with(String json,Check check)throws Exception{Path root=Files.createTempDirectory("goforge-dev-plan-");Path file=Files.writeString(root.resolve("devcontainer.json"),json);try{check.run(DevContainerPlan.read(root,file,"test"));}finally{Files.delete(file);Files.delete(root);}}
}
